package com.coffeeshop.service;
import com.coffeeshop.dto.*;import com.coffeeshop.model.*;import com.coffeeshop.repository.PosRepository;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class PosServiceTest {
 private final Stub repo=new Stub();private final PosService service=new PosService(repo);private final CartLine line=new CartLine(new MenuVariant(1,1,1,"Latte","Regular",new BigDecimal("3.2500"),null,null,null));
 @Test void calculatesMoneyWithBigDecimal(){line.increment();assertEquals(new BigDecimal("6.5000"),service.subtotal(List.of(line)));}@Test void requiresItems(){assertThrows(IllegalArgumentException.class,()->service.saveOpenOrder(new CreateOrderRequest(1,OrderType.TAKEAWAY,null,null,List.of())));}@Test void requiresTableForDineIn(){assertThrows(IllegalArgumentException.class,()->service.saveOpenOrder(new CreateOrderRequest(1,OrderType.DINE_IN,null,null,List.of(line))));}@Test void requiresCompleteDeliveryData(){assertThrows(IllegalArgumentException.class,()->service.saveOpenOrder(new CreateOrderRequest(1,OrderType.DELIVERY,null,new DeliveryInfo("Name","","Address","City"),List.of(line))));}@Test void validTakeawayPersists(){var q=new CreateOrderRequest(1,OrderType.TAKEAWAY,null,null,List.of(line));assertEquals("ORD00000001",service.saveOpenOrder(q));assertEquals(q,repo.saved);}
 private static final class Stub implements PosRepository{CreateOrderRequest saved;public List<MenuCategory>findActiveCategories(){return List.of();}public List<MenuVariant>findActiveMenuVariants(){return List.of();}public List<CafeTableInfo>findAvailableTables(){return List.of();}public String createOpenOrder(CreateOrderRequest q){saved=q;return"ORD00000001";}}
}
